class TreeAncestor {
  private final int[][] up;

  public TreeAncestor(int n, int[] parent) {
    int log = 1;
    while ((1L << log) <= n) log++;
    up = new int[log][n];
    up[0] = parent.clone();
    for (int j = 1; j < log; j++)
      for (int i = 0; i < n; i++) {
        int middle = up[j - 1][i];
        up[j][i] = middle == -1 ? -1 : up[j - 1][middle];
      }
  }

  public int getKthAncestor(int node, int k) {
    for (int bit = 0; bit < up.length && k > 0 && node != -1; bit++, k >>= 1)
      if ((k & 1) != 0) node = up[bit][node];
    return k == 0 ? node : -1;
  }
}
